L, ell, v0 = 26.0, 0.3, 1.3              # ring length (m), body length (m), free speed
for T in [0.5, 1.0]:
    for N in [5, 15, 30, 45, 60]:
        s = L / N                               # equal spacing in the steady state
        v = min(v0, max(0.0, (s - ell) / T))
        print(f'T {T}: {N:2d} people, density {N/L:.2f} per m, speed {v:.2f} m/s, flow {N/L*v:.2f} per s')
